// JIT warm-up demo: a hot loop accelerates after profiling

function sumTo(n) {
  let s = 0;
  for (let i = 1; i <= n; i++) s += i;
  return s;
}

// First call: Ignition interprets the bytecode
console.time('cold');
console.log(sumTo(1_000_000)); // 500000500000
console.timeEnd('cold');

// Repeat calls: TurboFan has compiled sumTo to native code
console.time('warm');
console.log(sumTo(1_000_000)); // same result, typically faster
console.timeEnd('warm');

// Type consistency matters for JIT optimisation:
function add(a, b) { return a + b; }
add(1, 2);       // JIT profiles: always numbers
add(1, 2);       // fast native path
add('x', 'y');   // different type -> JIT deoptimises back to interpreter

